//! `status --check`'s well-formedness diagnostics -- covers what `validate`
//! (removed) used to check.

mod common;

use std::fs;
use std::process::{Command, ExitCode};

use callisto_cli::cli::{AddArgs, GlobalArgs, OutputFormat, StatusArgs};
use callisto_cli::commands;

use common::setup_polyglot_git_repo;

/// A git repository where a Cargo crate and an npm package share the same
/// bare name (`foo`), so a changeset entry naming bare `foo` is ambiguous
/// between them.
fn setup_ambiguous_name_git_repo() -> tempfile::TempDir {
    let dir = tempfile::tempdir().unwrap();
    let root = dir.path();

    callisto_fixtures::git::init_repo(root);

    fs::write(
        root.join("Cargo.toml"),
        "[workspace]\nmembers = [\"crates/foo\"]\nresolver = \"2\"\n",
    )
    .unwrap();
    fs::create_dir_all(root.join("crates/foo/src")).unwrap();
    fs::write(
        root.join("crates/foo/Cargo.toml"),
        "[package]\nname = \"foo\"\nversion = \"0.1.0\"\nedition = \"2021\"\n",
    )
    .unwrap();
    fs::write(root.join("crates/foo/src/lib.rs"), "pub fn hello() {}\n").unwrap();

    fs::create_dir_all(root.join("packages/foo")).unwrap();
    fs::write(
        root.join("packages/foo/package.json"),
        "{\n  \"name\": \"foo\",\n  \"version\": \"1.0.0\"\n}\n",
    )
    .unwrap();

    assert!(Command::new("git")
        .args(["add", "."])
        .current_dir(root)
        .status()
        .unwrap()
        .success());
    assert!(Command::new("git")
        .args(["commit", "-m", "Initial commit"])
        .current_dir(root)
        .status()
        .unwrap()
        .success());

    dir
}

fn global(root: &std::path::Path) -> GlobalArgs {
    GlobalArgs {
        format: OutputFormat::Json,
        cwd: root.to_path_buf(),
        dry_run: false,
    }
}

fn check_args() -> StatusArgs {
    StatusArgs {
        strict: false,
        check: true,
    }
}

#[test]
fn test_status_check_clean_workspace_exits_ok() {
    let dir = setup_polyglot_git_repo();
    let root = dir.path();
    let global = global(root);

    callisto_fixtures::scaffold_callisto(&global.cwd);
            .any(|record| record.package == ids.of(&bump.package) && !record.pending_changesets.is_empty());
        if has_changeset {
            continue;
        }
        diagnostics.push(Diagnostic {
            code: DiagnosticCode::InferredReleaseWithoutChangeset,
            severity: DiagnosticSeverity::Warning,
            message: format!(
                "`{}` has a pending release inferred from {commits} commit(s) and no changeset; the release pull request reads changesets only, so add one to release it",
                bump.package.display_name()
            ),
            package: Some(bump.package.clone()),
            path: None,
            governed_by: None,
            escalated_by: None,
        });
    }
    escalate(&mut diagnostics, opts.strict);
    ids.diagnostics(&mut diagnostics);

    let has_changesets = packages.iter().any(|p| !p.pending_changesets.is_empty());
    // Count of packages with a planned bump, post-cascade/fixed/linked-group --
    // the field a script now reads to detect pending changesets, since `--check`'s
    // exit code no longer signals it.
    let pending = packages.iter().filter(|p| p.pending_severity.is_some()).count() as u32;

    Ok(StatusReport {
        schema_version: PACKAGE_REPORT_SCHEMA_VERSION,
        has_changesets,
        pending,
        packages,
        diagnostics,
    })
}

