/// Runs bare `callisto release` (local route) against the fake publishers.
/// `home` isolates `~/.cargo` and `~/.npmrc`.
pub fn release_local(root: &Path, args: &[&str], home: &Path, publishers: FakePublishers<'_>) -> Output {
